#[macro_use]
extern crate rocket;

mod nav;
mod views;

use nav::Chrome;
use views::*;

use propel_rocket::PropelView;
use propel_runtime::{Assets, RenderError};
use rocket::fs::FileServer;
use rocket::http::{ContentType, Status};

/// The address of the site, for the sitemap and the robots file. Pages build
/// their own absolute URLs from it in `layouts/app.propel`.
const SITE_URL: &str = "https://propel.rocketboost.rs";

/// The compiled views: one `render` function per view, generated by build.rs.
/// They sit in their own module, so their names do not clash with the routes.
mod compiled {
    include!(concat!(env!("OUT_DIR"), "/propel_views.rs"));
}

/// Where `asset()` and `@vite()` find the built files, and the dev server
/// while `npm run dev` runs.
fn assets() -> Assets {
    Assets::new("public")
}

/// Sample data. A real app would load this from a database.
fn all_posts() -> Vec<Post> {
    vec![
        Post {
            id: 1,
            title: "Hello, Propel".into(),
            published_at: Some("2026-11-05".into()),
            body: "The first post, rendered by the dev renderer.".into(),
        },
        Post {
            id: 2,
            title: "A draft".into(),
            published_at: None,
            body: "Drafts have no date, so the @if takes its else branch.".into(),
        },
        Post {
            id: 3,
            title: "Escaping <b>works</b>".into(),
            published_at: Some("2026-11-06".into()),
            body: "Titles are escaped like every other text echo.".into(),
        },
    ]
}

/// Allows every crawler to fetch every page, and points it to the sitemap.
#[get("/robots.txt")]
fn robots() -> (ContentType, String) {
    (
        ContentType::Text,
        format!("User-agent: *\nAllow: /\nDisallow:\n\nSitemap: {SITE_URL}/sitemap.xml\n"),
    )
}

/// The home page and the documentation pages, from the navigation. The demo
/// pages are not listed.
#[get("/sitemap.xml")]
fn sitemap() -> (ContentType, String) {
    let mut xml = String::from(
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n\
         <urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n",
    );
    for path in nav::sitemap_paths() {
        xml.push_str(&format!(
            "  <url>\n    <loc>{SITE_URL}{path}</loc>\n    <lastmod>2026-11-09</lastmod>\n  </url>\n"
        ));
    }
    xml.push_str("</urlset>\n");
    (ContentType::new("application", "xml"), xml)
}

#[get("/")]
fn home() -> PropelView {
    let chrome = Chrome::at("/");
    PropelView::from_result(compiled::home::render(
        &Article {
            title: "Introduction".into(),
            nav: chrome.nav,
            pager: chrome.pager,
        },
        &assets(),
    ))
}

/// The documentation pages. The address must be in the sidebar, so only the
/// pages the navigation lists are served.
#[get("/docs/<page>")]
fn docs(page: &str) -> Result<PropelView, (Status, PropelView)> {
    let path = format!("/docs/{page}");

    let Some(title) = nav::title(&path) else {
        return Err(not_found_page());
    };

    let chrome = Chrome::at(&path);
    let context = Article {
        title,
        nav: chrome.nav,
        pager: chrome.pager,
    };
    match render_docs(page, &context) {
        Some(result) => Ok(PropelView::from_result(result)),
        None => Err(not_found_page()),
    }
}

/// The documentation page `page`, as a compiled view. `None` for a name that
/// has no view, so the page is a 404.
pub(crate) fn render_docs(page: &str, ctx: &Article) -> Option<Result<String, RenderError>> {
    let assets = assets();
    Some(match page {
        "assets" => compiled::docs::assets::render(ctx, &assets),
        "components" => compiled::docs::components::render(ctx, &assets),
        "context" => compiled::docs::context::render(ctx, &assets),
        "install" => compiled::docs::install::render(ctx, &assets),
        "layouts" => compiled::docs::layouts::render(ctx, &assets),
        "syntax" => compiled::docs::syntax::render(ctx, &assets),
        "vite-tailwind" => compiled::docs::vite_tailwind::render(ctx, &assets),
        _ => return None,
    })
}

#[get("/posts")]
fn posts() -> PropelView {
    let chrome = Chrome::at("/posts");
    PropelView::from_result(compiled::posts::index::render(
        &PostsIndex {
            title: "Posts".into(),
            posts: all_posts(),
            nav: chrome.nav,
            pager: chrome.pager,
        },
        &assets(),
    ))
}

/// The id is read as text, so a value that is not a number gets the same 404
/// page as an unknown one, not Rocket's own 422.
#[get("/posts/<id>")]
fn post(id: &str) -> Result<PropelView, (Status, PropelView)> {
    let found = id
        .parse::<u32>()
        .ok()
        .and_then(|id| all_posts().into_iter().find(|post| post.id == id));

    match found {
        Some(post) => {
            let chrome = Chrome::at(&format!("/posts/{id}"));
            Ok(PropelView::from_result(compiled::posts::show::render(
                &PostShow {
                    post,
                    nav: chrome.nav,
                    pager: chrome.pager,
                },
                &assets(),
            )))
        }
        None => Err(not_found_page()),
    }
}

