/// A debug-only demo: the dev renderer reads the view from disk, so this
/// route exists in debug builds only. See build.rs.
#[cfg(debug_assertions)]
#[get("/errors/missing")]
fn missing() -> PropelView {
    // The view names `$not_in_context`, which this context does not have.
    let chrome = Chrome::at("/errors/missing");
    PropelView::render(
        "errors.missing",
        &Article {
            title: "Missing variable".into(),
            nav: chrome.nav,
            pager: chrome.pager,
        },
    )
}

/// A debug-only demo, as `missing`.
#[cfg(debug_assertions)]
#[get("/errors/nested-section")]
fn nested_section() -> PropelView {
    let chrome = Chrome::at("/errors/nested-section");
    PropelView::render(
        "errors.nested_section",
        &Article {
            title: "Nested section".into(),
            nav: chrome.nav,
            pager: chrome.pager,
        },
    )
}

fn not_found_page() -> (Status, PropelView) {
    let chrome = Chrome::at("");
    (
        Status::NotFound,
        PropelView::from_result(compiled::errors::not_found::render(
            &NoFields {
                nav: chrome.nav,
                pager: chrome.pager,
            },
            &assets(),
        )),
    )
}

#[catch(404)]
fn not_found() -> (Status, PropelView) {
    not_found_page()
}

#[launch]
fn rocket() -> _ {
    // `mut` is needed only in debug builds, which add the two demo routes.
    #[allow(unused_mut)]
    let mut routes = routes![
        home, robots, sitemap, docs, posts, post, escaping, control, dump, dd, cache
    ];
    #[cfg(debug_assertions)]
    routes.extend(routes![missing, nested_section]);

    rocket::build()
        .mount("/", routes)
        // Built assets: hashed files and copied images and fonts.
        .mount("/build", FileServer::new("public/build"))
        .register("/", catchers![not_found])
}
